import Vue from 'vue';
import VueRouter from 'vue-router';
Vue.use(VueRouter);
var routes = [{
  path: '/',
  name: '',
  component: function component() {
    return import('../views/Home.vue');
  },
  redirect: '/index',
  children: [{
    path: '/index',
    name: 'index',
    component: function component() {
      return import('../views/home/index.vue');
    }
  }, {
    path: '/index2',
    name: 'index2',
    component: function component() {
      return import('../views/home/index2.vue');
    }
  }, {
    path: '/examples',
    name: 'examples',
    component: function component() {
      return import('../views/examples/index.vue');
    }
  }, {
    path: '/docs/:nameId',
    name: 'docs',
    component: function component() {
      return import('../views/docs/index.vue');
    }
  }, {
    path: '/application',
    name: 'application',
    component: function component() {
      return import('../views/application/index.vue');
    }
  }, {
    path: '/editor',
    name: 'editor',
    component: function component() {
      return import('../views/editor/index.vue');
    }
  }]
}];
var router = new VueRouter({
  routes: routes
});
export default router;
